/* Live updates via lightweight polling (serverless-compatible replacement for SSE).
   Fast game poll while playing; slower poll for lobbies, standings and personal notices. */
let gameTimer=null,lobbyTimer=null,notifState=null;
function stopLive(){if(gameTimer){clearInterval(gameTimer);gameTimer=null}if(lobbyTimer){clearInterval(lobbyTimer);lobbyTimer=null}}
function connectLive(){
 stopLive();
 if(!state.boot.user){notifState=null;return}
 notifState=notifState||{w:state.boot.user.stats?.warnings||0,p:0};
 lobbyTimer=setInterval(async()=>{try{const ae=document.activeElement;if(state.modal||(ae&&['INPUT','TEXTAREA','SELECT'].includes(ae.tagName)))return;if([...document.querySelectorAll('form')].some(f=>[...f.elements].some(el=>(el.tagName==='INPUT'||el.tagName==='TEXTAREA')&&el.value!==el.defaultValue)))return;
   const n=await request('/api/notifications');
   if(n.warnings>notifState.w)notify(`Fair-play ruling: ${n.warnings} confirmed warning(s). Open your profile for details.`,true);
   if(n.prizes>notifState.p)notify('Your prize vault has an update.');
   notifState={w:n.warnings,p:n.prizes};
   await reload();
 }catch{}},5000);
 gameTimer=setInterval(async()=>{try{
   if(state.page!=='play'||!state.game?.id||state.game.status!=='active')return;
   const r=await request('/api/games/'+state.game.id),prev=state.game;
   state.game=r.game;state.game._receivedAt=Date.now();
   if(r.game.status!=='active'){await reload();return}
   if(JSON.stringify(r.game.moves)!==JSON.stringify(prev.moves)||r.game.draw_offer_by!==prev.draw_offer_by)render();
 }catch{}},1300);
}
