setInterval(updateClocks,250);
(async()=>{addEventListener('keydown',e=>{if(state.page!=='learn'||/INPUT|TEXTAREA|SELECT/.test(document.activeElement?.tagName||''))return;const L=LESSONS[state.lesson];if(e.key==='ArrowRight'&&state.lessonStep<L.line.length){state.lessonStep++;render()}else if(e.key==='ArrowLeft'&&state.lessonStep>0){state.lessonStep--;render()}});try{state.boot=await request('/api/bootstrap');route();connectLive();}catch(e){$('#app').innerHTML=`<div class="boot"><div class="boot-icon">♞</div><h3>Unable to connect to Knightfall</h3><p>${esc(e.message)}</p><button class="btn primary" data-act="retry-boot">Retry connection</button></div>`}})();

function kfSnap(){const f=[...document.querySelectorAll('form[data-form]')];const ae=document.activeElement;return{forms:f.map(fm=>({key:fm.dataset.form,vals:[...fm.elements].filter(el=>el.name&&el.type!=='file').map(el=>({n:el.name,v:el.value,c:el.checked}))})),fIdx:(ae&&ae.form)?f.indexOf(ae.form):-1,fName:(ae&&ae.name)||null,fPos:(ae&&ae.selectionStart!=null)?ae.selectionStart:null}}
function kfRestore(S){const forms=[...document.querySelectorAll('form[data-form]')];S.forms.forEach((sv,i)=>{const f=forms[i];if(!f||f.dataset.form!==sv.key)return;sv.vals.forEach(v=>{const el=f.elements[v.n];if(!el)return;try{if(el.type==='checkbox'||el.type==='radio')el.checked=v.c;else el.value=v.v}catch(e){}})});if(S.fIdx>=0&&forms[S.fIdx]&&S.fName){const el=forms[S.fIdx].elements[S.fName];if(el){try{el.focus();if(S.fPos!=null&&el.setSelectionRange)el.setSelectionRange(S.fPos,S.fPos)}catch(e){}}}}
function render(){const S=kfSnap();try{kfOrigRender();window.Kit&&Kit.refresh()}finally{kfRestore(S)}}
